library(ggplot2)
d<-readRDS('step3_examples.rds');invisible(list2env(d,environment()));dir.create('figures',showWarnings=FALSE)
C<-c('#2166AC','#B35806','#2A7F62','#80539B','#333333')
theme_set(theme_minimal(base_size=13)+theme(panel.grid.minor=element_blank(),plot.title.position='plot',plot.title=element_text(face='bold',size=16),strip.text=element_text(face='bold',size=12),legend.position='bottom',plot.margin=margin(12,18,12,12)))
savep<-function(name,p,w=11,h=5){ggsave(paste0('figures/',name,'.png'),ggplot_gtable(ggplot_build(p)),width=w,height=h,dpi=170,bg='white')}
# 1. Effective acquisition-grid weights, after quadrature and interpolation.
rr<-do.call(rbind,lapply(colnames(readouts),function(k)data.frame(time=0:44,value=readouts[,k],kernel=k)))
rr$kernel<-factor(rr$kernel,levels=c('linear','boxcar','triangle','gaussian'))
savep('01-readout',ggplot(subset(rr,time>=18&time<=23),aes(time-20.35,value))+geom_vline(xintercept=0,linetype=3,color='grey40')+geom_col(fill=C[1],width=.22)+facet_wrap(~kernel,ncol=2)+labs(x='Acquisition time relative to requested readout (s)',y='Weight on estimated activity',title='An epoch readout is a weighted average on the original time grid'),h=5.3)
# 2. Default vs low-ridge joint policy, in a null-feedback region.
p2<-do.call(rbind,lapply(c('Constant cue amplitude','Trial-varying cue amplitude'),function(case){pairs<-if(case=='Constant cue amplitude')list('Default policy (0.05)'=default,'Joint policy (0.02)'=joint) else list('Default policy (0.05)'=stress_default,'Joint policy (0.02)'=stress_joint);do.call(rbind,lapply(names(pairs),function(k){cf<-subset(pairs[[k]]$coefficients,voxel=='Cue_only');data.frame(lag=cf$lag,beta=cf$beta_corrected,policy=k,scenario=case)}))}))
p2$scenario<-factor(p2$scenario,levels=c('Constant cue amplitude','Trial-varying cue amplitude'))
savep('02-other-events',ggplot(p2,aes(lag,beta,color=policy,linetype=policy))+geom_hline(yintercept=0,color='grey40',linetype=3)+geom_line(linewidth=.9)+geom_point(size=2.2)+facet_wrap(~scenario)+scale_color_manual(values=C[1:2])+scale_linetype_manual(values=c('solid','dashed'))+labs(x='Lag from feedback onset (s)',y='Estimated feedback-source slope on x',color=NULL,linetype=NULL,title='A condition-mean correction cannot represent arbitrary cue variation'),h=4.8)
# 3. Same centered target-source amplitudes vs three readouts.
pt<-do.call(rbind,lapply(c('Raw readout','Target correction only','Cue + target correction'),function(mode){res<-switch(mode,'Raw readout'=raw,'Target correction only'=target_only,'Cue + target correction'=default);p<-subset(as.data.frame(res$panel),voxel=='Target'&evt_time==0);p$estimate<-if(mode=='Raw readout')p$decon_raw else p$decon_demixed;p$truth<-c(amp_target$run1[,'Target'],amp_target$run2[,'Target']);p$estimate<-ave(p$estimate,p$run,FUN=function(x)x-mean(x));p$truth<-ave(p$truth,p$run,FUN=function(x)x-mean(x));p$mode<-mode;p}))
pt$mode<-factor(pt$mode,levels=c('Raw readout','Target correction only','Cue + target correction'))
savep('03-target-readout',ggplot(pt,aes(truth,estimate,color=run,shape=run))+geom_abline(slope=1,intercept=0,linetype=3,color='grey40')+geom_point(size=2.4)+facet_wrap(~mode)+scale_color_manual(values=C[1:2])+scale_shape_manual(values=c(16,17))+scale_x_continuous(breaks=c(-1,0,1))+scale_y_continuous(breaks=c(-1,0,1))+coord_equal()+labs(x='Injected target amplitude, run-centered',y='Estimated readout, run-centered',color=NULL,shape=NULL,title='Gain and cross-event correction address different distortions'),h=4.4)
# 4. Response matrix before and after target de-mixing (with cue subtraction).
ha<-do.call(rbind,lapply(c('Raw target response','Corrected target response'),function(k){a<-if(k=='Raw target response')response_raw else response_default;data.frame(receiver=rep(1:20,20),source=rep(1:20,each=20),value=as.vector(a),panel=k)}));ha$panel<-factor(ha$panel,levels=unique(ha$panel))
savep('04-resolution',ggplot(ha,aes(source,receiver,fill=value))+geom_tile()+facet_wrap(~panel)+scale_fill_gradient2(low=C[2],mid='white',high=C[1],midpoint=0,limits=c(min(0,ha$value),max(1,ha$value)),breaks=c(0,.5,1),guide=guide_colourbar(barwidth=grid::unit(5,'cm')))+scale_x_continuous(breaks=c(1,5,10,15,20))+scale_y_reverse(breaks=c(1,5,10,15,20))+coord_equal()+labs(x='Injected target event',y='Receiving target readout',fill='Response',title='Regularized de-mixing moves the target response toward identity'),h=5)
# 5. Same duration-varying data; source height vs bin-integrated mass.
p5<-do.call(rbind,lapply(c('Impulse source','Duration: rate','Duration: integral'),function(k){res<-switch(k,'Impulse source'=duration_impulse,'Duration: rate'=duration_rate,'Duration: integral'=duration_integral);p<-as.data.frame(res$panel);p$model<-k;p$truth<-if(k=='Duration: integral')true_rate*p$duration/tr else true_rate;p}))
p5$model<-factor(p5$model,levels=c('Impulse source','Duration: rate','Duration: integral'))
savep('05-duration',ggplot(p5,aes(duration,decon_demixed,color=run,shape=run))+geom_line(aes(y=truth,group=1),color='grey30',linetype=3)+geom_point(size=2.3)+facet_wrap(~model,scales='free_y')+scale_color_manual(values=C[1:2])+scale_shape_manual(values=c(16,17))+labs(x='Generating source duration (s)',y='Estimated source amplitude',color=NULL,shape=NULL,title='Duration changes the estimand: response height and total activity differ'),h=4.7)
# 6. Actual beta_corrected and conditional trial SE, with optional lag correction.
p6<-do.call(rbind,lapply(c('No cross-lag correction','Cross-lag correction'),function(k){r<-if(k=='No cross-lag correction')default else within;cf<-subset(r$coefficients,voxel=='Target');p<-subset(as.data.frame(r$panel),voxel=='Target');se<-aggregate(se_demixed~evt_time,p,mean);rbind(data.frame(lag=cf$lag,value=cf$beta_corrected,mode=k,panel='Estimated beta_corrected'),data.frame(lag=se$evt_time,value=se$se_demixed,mode=k,panel='Mean conditional trial SE'))}))
p6$panel<-factor(p6$panel,levels=c('Estimated beta_corrected','Mean conditional trial SE'))
savep('06-cross-lag',ggplot(p6,aes(lag,value,color=mode,linetype=mode))+geom_line(linewidth=.95)+geom_point(size=2.2)+facet_wrap(~panel,ncol=1,scales='free_y')+scale_color_manual(values=C[1:2])+scale_linetype_manual(values=c('solid','dashed'))+labs(x='Lag from feedback (s)',y=NULL,color=NULL,linetype=NULL,title='Cross-lag correction changes both the trajectory and its noise'),h=5.8)
# 7. Known-noise validation of the complete fixed readout operator.
mc<-data.frame(trial=1:20,ratio=se_mc$empirical/se_mc$predicted)
savep('07-se-check',ggplot(mc,aes(trial,ratio))+geom_hline(yintercept=1,linetype=3,color='grey40')+geom_point(color=C[1],size=3)+scale_y_continuous(limits=c(.9,1.1),breaks=c(.9,.95,1,1.05,1.1))+scale_x_continuous(breaks=c(1,5,10,15,20))+labs(x='Target trial in run 1',y='Simulated SD / analytical SE',title='The fixed readout reproduces analytical measurement-noise uncertainty'),h=4.1)
# 8. Measurement-only precision vs biological-variance-stabilized precision.
p8<-subset(as.data.frame(default$panel),voxel=='Target'&evt_time==0)
p8<-rbind(data.frame(se=p8$se_demixed,weight=p8$precision_weight_op,kind='Operator-only precision'),data.frame(se=p8$se_demixed,weight=p8$precision_weight,kind='Biological + operator precision'))
savep('08-weights',ggplot(p8,aes(se,weight,color=kind,shape=kind))+geom_point(size=2.5)+scale_color_manual(values=C[1:2])+scale_shape_manual(values=c(16,4))+labs(x='Analytical trial measurement-error SE',y='Normalized precision weight',color=NULL,shape=NULL,title='Biological variability limits how strongly precise trials are upweighted'),h=4.4)
# 9. Regularized decorrelation, not exact whitening.
pre<-cov2cor(Sigma_tot);post<-cov2cor(Phi%*%Sigma_tot%*%t(Phi));diag(pre)<-diag(post)<-NA
hh<-rbind(data.frame(row=rep(1:20,20),col=rep(1:20,each=20),value=as.vector(pre),panel='Before regularized ZCA'),data.frame(row=rep(1:20,20),col=rep(1:20,each=20),value=as.vector(post),panel='After regularized ZCA'))
hh$panel<-factor(hh$panel,levels=c('Before regularized ZCA','After regularized ZCA'));mx<-max(abs(hh$value),na.rm=TRUE)
savep('09-decorrelation',ggplot(hh,aes(col,row,fill=value))+geom_tile()+facet_wrap(~panel)+scale_fill_gradient2(low=C[2],mid='white',high=C[1],midpoint=0,limits=c(-mx,mx),na.value='grey85',breaks=c(-.08,0,.08),labels=c('-0.08','0','0.08'),guide=guide_colourbar(barwidth=grid::unit(6,'cm')))+scale_x_continuous(breaks=c(1,5,10,15,20))+scale_y_reverse(breaks=c(1,5,10,15,20))+coord_equal()+labs(x='Trial',y='Trial',fill='Correlation',title='Regularized ZCA redistributes modeled cross-trial correlation'),h=4.9)
